export declare const ANNOTATIONS_STYLESHEET = "\n.rx-anno-popover {\n  position: absolute;\n  z-index: 70;\n  width: min(280px, 92vw);\n  background: var(--rx-surface);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  box-shadow: var(--rx-elevation); /* taste-skill-ignore: a real floating popover, not an at-rest surface */\n  padding: var(--rx-space-3);\n  display: flex;\n  flex-direction: column;\n  gap: var(--rx-space-2);\n}\n.rx-anno-popover[hidden] {\n  display: none;\n}\n.reader-shell.e-ink .rx-anno-popover {\n  border: 1px solid var(--rx-ink);\n}\n.rx-anno-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--rx-space-2);\n}\n.rx-anno-status {\n  font-size: 13px;\n  color: var(--rx-muted);\n}\n.rx-anno-close {\n  flex: 0 0 auto;\n}\n.rx-anno-colors {\n  display: flex;\n  gap: var(--rx-space-2);\n}\n.rx-anno-swatch {\n  width: 40px;\n  height: 48px;\n  min-width: 40px;\n  border: 2px solid transparent;\n  border-radius: var(--rx-radius);\n  background: var(--rx-surface-2);\n  cursor: pointer;\n  position: relative;\n}\n.rx-anno-swatch::before {\n  content: '';\n  position: absolute;\n  inset: 12px;\n  border-radius: 50%;\n  background: var(--rx-anno-swatch-color);\n}\n.reader-shell.e-ink .rx-anno-swatch::before {\n  border-radius: 0;\n}\n.rx-anno-swatch[aria-checked='true'] {\n  border-color: var(--rx-accent);\n}\n.rx-anno-styles {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--rx-space-2);\n}\n.rx-anno-style,\n.rx-anno-note-toggle,\n.rx-anno-note-save,\n.rx-anno-note-cancel,\n.rx-anno-delete {\n  min-height: 48px;\n  padding: 0 var(--rx-space-3);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  background: var(--rx-surface-2);\n  color: var(--rx-ink);\n  font-size: 13px;\n  cursor: pointer;\n}\n.rx-anno-style[aria-pressed='true'] {\n  border-color: var(--rx-accent);\n  color: var(--rx-accent);\n}\n.rx-anno-delete {\n  color: #c0392b;\n  border-color: #c0392b;\n}\n.rx-anno-note-form {\n  display: flex;\n  flex-direction: column;\n  gap: var(--rx-space-2);\n}\n.rx-anno-note-textarea {\n  min-height: 72px;\n  padding: var(--rx-space-2);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  background: var(--rx-ground);\n  color: var(--rx-ink);\n  font: inherit;\n  resize: vertical;\n}\n.rx-anno-note-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: var(--rx-space-2);\n}\n\n.rx-anno-selection-hint {\n  position: absolute;\n  z-index: 70;\n  background: var(--rx-surface);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  box-shadow: var(--rx-elevation); /* taste-skill-ignore: floating selection menu */\n  padding: var(--rx-space-1);\n}\n";
